const base=[['solana','Solana','SOL','◎','#a695ff',172.48,3.24,81900000000,3490000000,474830000,null,true],['bitcoin','Bitcoin','BTC','₿','#f6a744',96420.36,1.82,1910000000000,38500000000,19810000,21000000,false],['ethereum','Ethereum','ETH','Ξ','#93a5ef',3284.72,-.84,395000000000,17600000000,120300000,null,false],['jupiter-exchange-solana','Jupiter','JUP','J','#b6e99c',.9426,5.17,2545000000,148000000,2700000000,10000000000,true],['raydium','Raydium','RAY','R','#7bc9f5',4.86,2.63,1410000000,89000000,290000000,555000000,true],['bonk','Bonk','BONK','B','#f1bd75',.0000248,-2.14,1900000000,177000000,76610000000000,88872000000000,true],['chainlink','Chainlink','LINK','⬡','#6c9aff',18.74,1.36,11700000000,442000000,624000000,1000000000,false],['jito-governance-token','Jito','JTO','≋','#9cdec3',2.87,-1.23,910000000,64000000,317000000,1000000000,true],['usd-coin','USDC','USDC','$','#75afea',1.0001,.01,54000000000,5800000000,53994600000,null,true]].map((x,i)=>({id:x[0],name:x[1],symbol:x[2],glyph:x[3],color:x[4],current_price:x[5],price_change_percentage_24h:x[6],market_cap:x[7],total_volume:x[8],circulating_supply:x[9],max_supply:x[10],solana:x[11],fully_diluted_valuation:x[5]*(x[10]||x[9]*1.08),index:i}));
let coins=base.map(c=>({...c})),view='home',selected='solana',tab=0,range=1,filter='all',query='',mode='demo',busy=false,requestedLive=false,updated=null,compareA='solana',compareB='bitcoin',chartToken=0,chartCache={},chartState={points:null,real:false,loading:false,failed:false,key:null};
const $=s=>document.querySelector(s);const t=k=>packs[lang][k]??packs.en[k]??k;const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const interpolate=(s,o)=>s.replace(/\{(\w+)\}/g,(_,k)=>o[k]??'');
function num(v,d=2){return v==null||!Number.isFinite(v)?t('notavailable'):new Intl.NumberFormat(t('locale'),{maximumFractionDigits:d}).format(v)}
function money(v,compact=false){if(v==null||!Number.isFinite(v))return t('notavailable');return new Intl.NumberFormat(t('locale'),{style:'currency',currency:'USD',notation:compact?'compact':'standard',maximumFractionDigits:compact?2:v<.01?8:v<1?4:2}).format(v)}
function pct(v){return v==null?t('notavailable'):`${v>0?'+':''}${num(v)}%`}
function coinIcon(c){return `<span class="coinicon" style="background:${c.color}17;color:${c.color}">${c.glyph}</span>`}
function nav(){const keys=['home','watch','compare','learn'];const n=keys.map((k,i)=>`<button class="${view===k||(view==='detail'&&k==='home')?'active':''}" onclick="navigate('${k}')">${t('nav')[i]}</button>`).join('');$('#desktopnav').innerHTML=n;$('#bottomnav').innerHTML=keys.map((k,i)=>`<button class="${view===k||(view==='detail'&&k==='home')?'active':''}" onclick="navigate('${k}')">${svg(['home','star','compare','learn'][i])}<span>${t('nav')[i]}</span></button>`).join('');document.documentElement.lang=lang;document.title='Mercek • '+t('nav')[0];document.querySelector('.brand').setAttribute('aria-label','Mercek • '+t('nav')[0]);document.querySelector('.headerend .pill').textContent=t('ecosystem');document.querySelector('.avatar').setAttribute('aria-label',t('about'));let l=$('#langselect');if(!l){l=document.createElement('select');l.id='langselect';l.className='langselect';l.style.cssText='background:#192331;color:#eef3fa;border:1px solid #263141;border-radius:8px;padding:7px 6px;max-width:106px;font-size:13px';l.onchange=e=>{lang=e.target.value;safeSet('mercek-lang',lang);render()};document.querySelector('.headerend').prepend(l)}l.setAttribute('aria-label',t('language'));l.innerHTML=Object.entries(languages).map(([k,v])=>`<option value="${k}" ${k===lang?'selected':''}>${v}</option>`).join('')}
function status(){return `<div class="sourcebar"><span class="top-note">${busy?t('loading'):mode==='live'?t('liveNotice'):t('modeNotice')}</span><button class="refresh" onclick="${mode==='live'?'setDemo()':'loadLive()'}" ${busy?'disabled':''}>${mode==='live'?t('demoMode'):t('liveMode')}</button></div>`}
function intro(title,sub){return `<div class="intro"><div><div class="eyebrow">${t('solanaFocus')}</div><h1>${title}</h1><p>${sub}</p></div><span class="date">${new Intl.DateTimeFormat(t('locale'),{day:'numeric',month:'long',year:'numeric'}).format(new Date())}</span></div>`}
function searchbar(){return `<div class="searchrow"><label class="search">${svg('search')}<input id="searchinput" type="search" placeholder="${t('search')}" aria-label="${t('search')}" value="${esc(query)}" oninput="searchCoins(this.value)"></label><button class="btn" onclick="loadLive()" aria-label="${t('refresh')}" ${busy?'disabled':''}>${svg('refresh')}${t('refresh')}</button></div>`}
function spark(c){const real=mode==='live'&&Array.isArray(c.sparkline_in_7d?.price)&&c.sparkline_in_7d.price.length>1;const p=real?c.sparkline_in_7d.price:demoPoints(c,1);return `<svg class="spark" viewBox="0 0 76 30" aria-label="${t(real?'chartLive':'chartDemo')}"><polyline fill="none" stroke="${c.price_change_percentage_24h>=0?'#64dec0':'#ff8a96'}" stroke-width="1.6" points="${normalise(p,76,26,2)}"/></svg>`}
function demoPoints(c,r){let s=c.index*53+r*37+129;return Array.from({length:65},(_,i)=>{s=(s*9301+49297)%233280;return 80+Math.sin(i*.22+r)*10+(s/233280-.5)*8+i*(c.price_change_percentage_24h>=0?.38:-.27)})}
function normalise(p,w,h,pad=12){let min=Math.min(...p),max=Math.max(...p);return p.map((v,i)=>`${(pad+i/(p.length-1)*(w-2*pad)).toFixed(1)},${(h-pad-(v-min)/(max-min||1)*(h-2*pad)).toFixed(1)}`).join(' ')}
function rows(){let list=coins.filter(c=>(view!=='watch'||watch.includes(c.id))&&(filter!=='solana'||c.solana)&&(filter!=='watch'||watch.includes(c.id))&&(!query||`${c.name} ${c.symbol}`.toLowerCase().includes(query.toLowerCase())));return `<div class="market"><div class="tablehead"><span>${t('asset')}</span><span>${t('price')}</span><span>${t('day')}</span><span class="sparkcol">${t(mode==='live'?'trend':'demo')}</span><span></span></div>${list.length?list.map(c=>`<div class="coinrow" onclick="openCoin('${c.id}')" role="link" tabindex="0" onkeydown="if(event.key==='Enter')openCoin('${c.id}')"><div class="coinidentity">${coinIcon(c)}<div><div class="coinname">${c.name}</div><div class="symbol">${c.symbol}</div></div></div><div class="value">${money(c.current_price)}</div><div class="value ${c.price_change_percentage_24h>=0?'positive':'negative'}">${pct(c.price_change_percentage_24h)}</div><span class="sparkcol">${spark(c)}</span><button class="star ${watch.includes(c.id)?'selected':''}" aria-label="${watch.includes(c.id)?t('remove'):t('add')} ${c.name}" aria-pressed="${watch.includes(c.id)}" onclick="event.stopPropagation();toggleWatch('${c.id}')">${watch.includes(c.id)?'★':'☆'}</button></div>`).join(''):`<div class="empty">${view==='watch'&&!watch.length?t('empty'):t('noresults')}</div>`}</div>`}
function sidebar(){return `<aside class="sidebar"><section class="panel"><div style="display:flex;justify-content:space-between"><h3>${t('changes')}</h3><span class="badge">MERCEK</span></div><div class="sideitem"><span class="sidelabel">◈ ${t('guide')}</span><strong style="font-size:14px;display:block;margin-top:9px">${t('note1')}</strong><p>${t('note1body')}</p></div><div class="sideitem"><span class="sidelabel">◈ ${t('guide')}</span><strong style="font-size:14px;display:block;margin-top:9px">${t('note2')}</strong><p>${t('note2body')}</p></div></section><section class="panel tip"><span class="eyebrow">${t('nav')[3]}</span><h3 style="margin:12px 0">${t('learnhead')}</h3><p>${t('learnbody')}</p><button class="textbutton" onclick="navigate('learn')">${t('learncta')}</button></section><section class="panel" style="background:transparent"><h3>${t('method')}</h3><p>${t('methodbody')}</p><button class="textbutton" onclick="showInfo()">${t('about')}</button></section></aside>`}
function home(){return `${intro(t(view==='watch'?'watchtitle':'hello'),t(view==='watch'?'watchsub':'sub'))}${searchbar()}${status()}<div class="grid"><div>${view==='home'?`<section class="hero"><div class="orb"></div><span class="eyebrow">${t('eyebrow')}</span><h2>${t('hero')}</h2><p>${t('herosub')}</p><button class="btn primary" onclick="openCatalog()">${t('open')}</button></section>`:''}<div class="sectionhead"><h2>${view==='watch'?t('nav')[1]:t('market')}</h2><span>${view==='watch'?coins.filter(c=>watch.includes(c.id)).length:coins.length} ${t('assets')}</span></div><div class="filters">${[['all','all'],['solana','solana'],['watch','favorites']].map(([key,label])=>key==='solana'&&typeof ecosystemFilterButton==='function'?ecosystemFilterButton():`<button class="chip ${filter===key?'active':''}" onclick="setFilter('${key}')">${t(label)}</button>`).join('')}</div><div id="rows">${rows()}</div><div class="sourcebar"><span>${mode==='live'?'CoinGecko Public API':t('demoDate')}</span><span>${updated?new Intl.DateTimeFormat(t('locale'),{hour:'2-digit',minute:'2-digit'}).format(updated):'—'}</span></div></div>${sidebar()}</div>`}
function summary(c){let text=interpolate(t(c.price_change_percentage_24h==null?'summaryFlat':c.price_change_percentage_24h>=0?'summaryUp':'summaryDown'),{name:c.name,change:num(Math.abs(c.price_change_percentage_24h||0))});if(c.total_volume!=null&&c.market_cap>0)text+=' '+interpolate(t('summaryVol'),{volume:money(c.total_volume,true),ratio:num(c.total_volume/c.market_cap*100)});return `<section class="summary"><h3>✧ ${t('auto')}</h3><p>${text}</p><small>${t('autolabel')}</small><small style="color:${mode==='demo'?'var(--gold)':'var(--muted)'}">${t(mode==='demo'?'summaryDemo':'summaryLive')}</small></section>`}
function metrics(c) {
  const cells = [
    ['cap', c.market_cap, () => money(c.market_cap,true)],
    ['volume', c.total_volume, () => money(c.total_volume,true)],
    ['supply', c.circulating_supply, () => num(c.circulating_supply,0)+' '+c.symbol],
    ['fdv', c.fully_diluted_valuation, () => money(c.fully_diluted_valuation,true)],
    ['max', c.max_supply, () => num(c.max_supply,0)],
    ['turnover', c.market_cap>0 && Number.isFinite(c.total_volume) ? 100*(c.total_volume/c.market_cap) : null, value => num(value)+'%']
  ];
  return `<div class="metrics">${cells.map(([key,value,format]) =>
    `<div class="metric"><label>${t(key)}</label>${Number.isFinite(value)
      ? `<strong>${format(value)}</strong>`
      : `<strong class="metric-unavailable">${t('notavailable')}</strong>`}</div>`
  ).join('')}</div>`;
}
function chart(c){let real=chartState.real&&chartState.key===`${c.id}-${range}`;let p=real?chartState.points:demoPoints(c,range);const points=normalise(p,700,220,10);return `<div class="chartwrap"><svg viewBox="0 0 700 220" preserveAspectRatio="none" role="img" aria-label="${t(real?'chartLive':'chartDemo')}"><defs><linearGradient id="chartfill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#b6f36a" stop-opacity=".22"/><stop offset="100%" stop-color="#b6f36a" stop-opacity="0"/></linearGradient></defs>${[40,90,140,190].map(y=>`<line x1="0" x2="700" y1="${y}" y2="${y}" stroke="#263141" stroke-dasharray="4 6"/>`).join('')}<polygon points="10,220 ${points} 690,220" fill="url(#chartfill)"/><polyline points="${points}" fill="none" stroke="#b6f36a" stroke-width="2.4" vector-effect="non-scaling-stroke"/></svg></div><div class="chartcaption">${chartState.loading?t('chartWaiting'):t(real?'chartLive':'chartDemo')}</div>${chartState.failed&&mode==='live'?`<p class="chartcaption">${t('chartFailed')}</p>`:''}`}
function detail(){const c=coins.find(c=>c.id===selected)||coins[0];return `<div class="detailtop"><button class="textbutton" onclick="navigate('home')">‹ ${t('back')}</button><span class="pill">${t(mode==='live'?'live':'demo')}</span></div><div class="detailtop"><div class="detailtitle">${coinIcon(c)}<div><h1>${c.name}</h1><span class="symbol">${c.symbol} · ${c.solana?t('solana'):t('main')}</span></div></div><button class="btn ${watch.includes(c.id)?'':'primary'}" onclick="toggleWatch('${c.id}')">${watch.includes(c.id)?'★':'☆'} ${t(watch.includes(c.id)?'remove':'add')}</button></div>${status()}<div class="grid"><div><div class="pricebig"${Number.isFinite(c.current_price)?'':' data-quote-missing'}>${money(c.current_price)}</div><div class="${!Number.isFinite(c.price_change_percentage_24h)?'':c.price_change_percentage_24h>=0?'positive':'negative'}">${pct(c.price_change_percentage_24h)} <span style="font-size:13px;color:var(--muted)">${t('day')}</span></div><div class="tabs">${t('tabs').map((v,i)=>`<button class="tab ${tab===i?'active':''}" onclick="setTab(${i})">${v}</button>`).join('')}</div>${tab===0?`<div style="display:flex;justify-content:end"><div class="ranges">${t('ranges').map((label,i)=>`<button class="chip ${range===i?'active':''}" onclick="setRange(${i})">${label}</button>`).join('')}</div></div>${chart(c)}${summary(c)}${metrics(c)}`:tab===1?`${metrics(c)}<section class="panel" style="margin-top:24px"><h3>${t('why')}</h3>${t('metricHelp').map(x=>`<p>${x}</p>`).join('')}</section>`:tab===2?`<section class="panel"><span class="eyebrow">${t('guide')}</span><h3 style="margin-top:12px">${t('securityTitle')}</h3><div class="notice">${t('securityNote')}</div>${t('riskNames').map((v,i)=>`<div class="riskrow"><div style="display:flex;justify-content:space-between;gap:10px"><strong>${v}</strong><span class="unknown">${t('unknown')}</span></div><p>${t('riskBodies')[i]}</p></div>`).join('')}</section>`:`<section class="panel"><h3>${t('sourceTitle')}</h3><p>${t('sourceBody')}</p><p>${t('sourceDemo')}</p><p>${t('sourceRisk')}</p><p><strong>${t('time')}:</strong> ${mode==='demo'?t('demoDate'):Number.isFinite(Date.parse(c.last_updated))?new Intl.DateTimeFormat(t('locale'),{dateStyle:'medium',timeStyle:'short'}).format(new Date(c.last_updated)):t('notavailable')}</p><p><a href="https://www.coingecko.com/en/coins/${c.id}" target="_blank" rel="noopener">${t('viewSource')}</a></p>${c.solana?`<p><a href="https://solana.com/docs/tokens" target="_blank" rel="noopener">${t('solDocs')}</a></p>`:''}</section>`}</div>${sidebar()}</div>`}
function comparison() {
  return `${intro(t('compareTitle'),t('compareSub'))}${status()}`;
}
function comparisonResults(a,b) {
  const metrics=[
    ['price',c=>money(c.current_price)],['day',c=>pct(c.price_change_percentage_24h)],
    ['cap',c=>money(c.market_cap,true)],['volume',c=>money(c.total_volume,true)],
    ['supply',c=>num(c.circulating_supply,0)],['max',c=>num(c.max_supply,0)],
    ['turnover',c=>c.market_cap>0&&Number.isFinite(c.total_volume)?num(c.total_volume/c.market_cap*100)+'%':t('notavailable')]
  ];
  const cell = (asset,value) => asset ? value(asset) : t('notavailable');
  return `<section class="panel compare-results">
    <table class="comparetable"><thead><tr><th scope="col">${t('tabs')[1]}</th><th scope="col">${a?esc(a.name):'—'}</th><th scope="col">${b?esc(b.name):'—'}</th></tr></thead>
    <tbody>${metrics.map(([key,value])=>`<tr><td>${t(key)}</td><td>${cell(a,value)}</td><td>${cell(b,value)}</td></tr>`).join('')}</tbody></table>
    <div class="notice">${t('compareNote')}</div>
  </section>
  <div class="compare-summaries">${[a,b].filter(asset=>Number.isFinite(asset?.current_price)).map(summary).join('')}</div>`;
}
function learn(){return `${intro(t('learnTitle'),t('learnSub'))}<div class="lessons">${t('lessons').map(([title,body],i)=>`<article class="lesson"><span class="num">${String(i+1).padStart(2,'0')} / MERCEK</span><h3>${title}</h3><p>${body}</p></article>`).join('')}</div><div class="notice">${t('securityNote')}</div>`}
function render(){nav();$('#app').innerHTML=(view==='home'||view==='watch'?home():view==='detail'?detail():view==='compare'?comparison():learn())+`<footer class="footer">${t('footer')} <button class="textbutton" onclick="showInfo()">${t('about')}</button></footer>`}
function navigate(v){view=v;query='';filter='all';render();window.scrollTo({top:0,behavior:'smooth'});history.replaceState(null,'',`#${v}`)}
function openCoin(id){selected=id;view='detail';tab=0;range=1;chartState={points:null,real:false,loading:false,failed:false,key:null};render();window.scrollTo({top:0,behavior:'smooth'});history.replaceState(null,'',`#token/${id}`);if(mode==='live')fetchChart()}
function toggleWatch(id){if(watch.includes(id)){watch=watch.filter(x=>x!==id);toast(t('removed'))}else{watch.push(id);toast(t('added'))}safeSet('mercek-watch',JSON.stringify(watch));render()}
function searchCoins(v){query=v;$('#rows').innerHTML=rows()}
function setFilter(f){filter=f;render();if(query){$('#searchinput')?.focus()}}
function setTab(i){tab=i;render()}
function setRange(i){range=i;chartState={points:null,real:false,loading:false,failed:false,key:null};render();if(mode==='live')fetchChart()}
let toastTimer;function toast(text){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,4500)}
function showInfo(){const d=$('#info');d.innerHTML=`<h2>${t('aboutTitle')}</h2><p>${t('aboutBody')}</p><p>${t('sourceBody')}</p><p>${t('aboutChain')}</p><h3 style="font-size:16px">${t('installTitle')}</h3><p>${t('installBody')}</p><button class="btn primary" onclick="document.querySelector('#info').close()">${t('close')}</button>`;d.showModal()}
async function request(url){const ctrl=new AbortController();const timeout=setTimeout(()=>ctrl.abort(),11000);try{const r=await fetch(url,{signal:ctrl.signal});if(!r.ok)throw Error('API '+r.status);return await r.json()}finally{clearTimeout(timeout)}}
async function loadLive(){if(busy)return;busy=true;render();try{const data=await request('https://api.coingecko.com/api/v3/coins/markets?vs_currency=usd&ids='+base.map(c=>c.id).join(',')+'&order=market_cap_desc&per_page=20&page=1&sparkline=true');if(!Array.isArray(data)||!data.length)throw Error('No data');const merged=base.map(c=>{const live=data.find(x=>x.id===c.id);if(!live||!Number.isFinite(live.current_price))return null;return {...c,...live,symbol:c.symbol,solana:c.solana,color:c.color,glyph:c.glyph,index:c.index}}).filter(Boolean);if(merged.length!==base.length)throw Error('Incomplete data');coins=merged;mode='live';updated=new Date();requestedLive=true;chartCache={};chartState={points:null,real:false,loading:false,failed:false,key:null};}catch{toast(t('fallback'));if(mode!=='live'){coins=base.map(c=>({...c}));mode='demo'}}finally{busy=false;render();if(mode==='live'&&view==='detail')fetchChart()}}
function setDemo(){coins=base.map(c=>({...c}));mode='demo';updated=null;chartToken++;chartState={points:null,real:false,loading:false,failed:false,key:null};render()}
async function fetchChart(){let token=++chartToken,key=`${selected}-${range}`;if(chartCache[key]){chartState={points:chartCache[key],real:true,loading:false,failed:false,key};render();return}chartState={points:null,real:false,loading:true,failed:false,key};render();try{let data=await request(`https://api.coingecko.com/api/v3/coins/${selected}/market_chart?vs_currency=usd&days=${[1,7,30,365,730][range]}`);if(!Array.isArray(data.prices)||data.prices.length<2)throw Error('No history');let p=data.prices.map(x=>x[1]).filter(Number.isFinite);if(p.length<2)throw Error('No history');if(p.length>180)p=p.filter((_,i)=>i%Math.ceil(p.length/180)===0);chartCache[key]=p;if(token!==chartToken||mode!=='live')return;chartState={points:p,real:true,loading:false,failed:false,key};}catch{if(token!==chartToken||mode!=='live')return;chartState={points:null,real:false,loading:false,failed:true,key}}if(view==='detail')render()}
if(location.hash.startsWith('#token/')){const id=location.hash.slice(7);if(base.some(c=>c.id===id)){view='detail';selected=id}}else if(['watch','compare','learn'].includes(location.hash.slice(1)))view=location.hash.slice(1);
render();
if('serviceWorker' in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});
